import{_ as a,C as r,o,c as n,j as e,a as i,E as d,a6 as h}from"./chunks/framework.CCKCzdWs.js";const l="/screenshots/vscode-test-card.png",c="/screenshots/jetbrains-test-card.png",_=JSON.parse(`{"title":"Test card","description":"A test's card in VS Code's hover and on a click of its result icon in a JetBrains IDE: its latest runs as a strip, each linked to its run, how many passed, its median duration, its last failure, its owner, tags and quarantine.","frontmatter":{"title":"Test card","description":"A test's card in VS Code's hover and on a click of its result icon in a JetBrains IDE: its latest runs as a strip, each linked to its run, how many passed, its median duration, its last failure, its owner, tags and quarantine.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/editor-test-card.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/editor-test-card.html"}],["meta",{"property":"og:title","content":"Test card | Piwi for Playwright"}],["meta",{"property":"og:description","content":"A test's card in VS Code's hover and on a click of its result icon in a JetBrains IDE: its latest runs as a strip, each linked to its run, how many passed, its median duration, its last failure, its owner, tags and quarantine."}]]},"headers":[],"relativePath":"features/editor-test-card.md","filePath":"features/editor-test-card.md","lastUpdated":1795476289000}`),u={name:"features/editor-test-card.md"};function p(f,t,m,g,w,k){const s=r("Needs");return o(),n("div",null,[t[0]||(t[0]=e("h1",{id:"test-card",tabindex:"-1"},[i("Test card "),e("a",{class:"header-anchor",href:"#test-card","aria-label":'Permalink to "Test card"'},"​")],-1)),d(s,{editor:""}),t[1]||(t[1]=h('<p>A test&#39;s card answers &quot;my bug or a flake?&quot; without leaving the editor. In VS Code it is the test&#39;s hover on its <code>test(…)</code> line; in a JetBrains IDE, a click on the test&#39;s result icon opens it.</p><figure><img src="'+l+'" alt="VS Code: the hover on a failing test&#39;s line, its card: the latest runs as colored bars, how many passed and the median duration, the run it last failed in and why, then Run, Open in dashboard and More…"><figcaption>VS Code: the card in the hover on the test&#39;s line.</figcaption></figure><figure><img src="'+c+'" alt="WebStorm: the card a click on a failing test&#39;s result icon opens: the test&#39;s title, its latest runs as colored bars and how they went, the run it last failed in and why, then Run, Open in dashboard and More…"><figcaption>A JetBrains IDE: the card a click on the test&#39;s result icon opens.</figcaption></figure><h2 id="what-it-shows" tabindex="-1">What it shows <a class="header-anchor" href="#what-it-shows" aria-label="Permalink to &quot;What it shows&quot;">​</a></h2><ul><li><strong>The strip</strong>: the test&#39;s latest runs, oldest on the left, one bar each in the dashboard&#39;s color for its outcome: green passed, red failed, fuchsia flaky (it passed on a retry), gray skipped. A run is one bar, whatever its retries, repetitions and projects: failed when one of them ended failed, flaky when one passed on a retry. Each bar links to its run, and its tooltip names the run, the outcome and how long the test took.</li><li><strong>How far back</strong>: twenty runs at most, read from the test&#39;s last 50 attempts, so a test run in three projects shows about sixteen, and one run with <code>--repeat-each</code> fewer still. The dashboard&#39;s test page holds its whole history.</li><li><strong>How they went</strong>: <code>Passed 17 of the last 20 runs · 2 flaky · median 1.4 s</code>, skipped runs left out.</li><li><strong>The last failure</strong>: the run it failed in, how long ago, and why in one line, in the editor&#39;s error color: the headline of its error (<code>Expected true, got false — toBe</code>).</li><li><strong>Its owner, tags and quarantine</strong>: the owner its <code>piwi:owner</code> annotation names, its Playwright tags, and, while it is <a href="./flaky-tests.html#quarantine-with-a-way-out">quarantined</a>, for how long and how many passes it has toward release.</li></ul><p>Under the card, <strong>Run</strong> runs the test, <strong>Open in dashboard</strong> opens its page, and <strong>More…</strong> opens the test&#39;s actions: <a href="./editor-runs.html">Runs from the editor</a> lists them.</p><h2 id="where-it-comes-from" tabindex="-1">Where it comes from <a class="header-anchor" href="#where-it-comes-from" aria-label="Permalink to &quot;Where it comes from&quot;">​</a></h2><p>The editor reads the test&#39;s history from the instance as the card opens, and keeps it for 30 seconds. It waits for it one and a half seconds at most: past that, the hover shows the test&#39;s result in one line, and a click in a JetBrains IDE opens the test&#39;s actions. A test the instance does not know yet has no card.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./editor-runs.html">Runs from the editor</a></li><li><a href="./flaky-tests.html">Flaky tests</a></li></ul>',10))])}const b=a(u,[["render",p]]);export{_ as __pageData,b as default};
